def max_rect(h,w,grid):
    # largest all-same-color rectangle via histogram per row
    best=(0,None,None)
    H,W=h,w
    import itertools
    # simple O(N^2) scan over color blocks
    seen=set()
    for a in range(H):
        for b in range(W):
            if (a,b) in seen: continue
            col=grid[a][b]; st=[(a,b)]; comp={(a,b)}
            while st:
                rr,cc=st.pop()
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=rr+dr,cc+dc
                        if (nr,nc) not in comp and 0<=nr<H and 0<=nc<W and grid[nr][nc]==col:
                            comp.add((nr,nc)); st.append((nr,nc))
            # largest square/rect containing comp? use bbox
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            area=(r1-r0+1)*(c1-c0+1)
            full=all(grid[j][k]==col for j in range(r0,r1+1) for k in range(c0,c1+1))
            seen|=comp
            if area>best[0]: best=(area,(r0,c0,col),full)
    return best
