    H,W=len(J),len(J[0])
    rs=[i for i in range(H) if len(set(J[i]))==1]
    cs=[j for j in range(W) if len({J[r][j] for r in range(H)})==1]
    blklist=[]
    for rb,rb2 in zip([-1]+rs,rs+[H]):
        for cb,cb2 in zip([-1]+cs,cs+[W]):
            blklist.append((rb,rb2,cb,cb2))
    sep=J[rs[0]][cs[0]]
    seen=[[False]*W for _ in range(H)]; best=(-1,None)
    for r in range(H):
        for c in range(W):
            if J[r][c]!=sep and not seen[r][c]:
                col=J[r][c]; st=[(r,c)]; cells=[]
                while st:
                    rr,cc=st.pop(); cells.append((rr,cc)); seen[rr][cc]=True
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and J[nr][nc]==col:
                            st.append((nr,nc))
                if best[0]<len(cells): best=(len(cells),col)
    # winning block bounds: containing a cell of the winner color, not sep... any cell of that color?
    winblk=None
    for r0,r1,c0,c1 in blklist:
        has=sum(1 for r in range(r0+1,r1) for c in range(c0+1,c1) if J[r][c]==best[1] and J[r][c]!=sep)
        if has: winblk=(r0,r1,c0,c1)
    out=[[J[r][c] for c in range(W)] for r in range(H)]
    for r in range(H):
        for c in range(W):
            v=J[r][c]
            if v!=sep:
                for r0,r1,c0,c1 in blklist:
                    if (r0+1,r1-1,c0+1,c1-1)==(r,r,c,c) or True: pass
                # determine which block this cell belongs to
                blocks_containing=[b for b in blklist if b[0]<r<b[1] and b[2]<c<b[3]]
                assert len(blocks_containing)==1
                r0,r1,c0,c1=blocks_containing[0]
                if (r0,r1,c0,c1)==winblk: out[r][c]=best[1]
                else: out[r][c]=collections.Counter(J[x][y] for x in range(r0+1,r1) for y in range(c0+1,c1)).most_common(1)[0][0]
    return out
